"""Parallel research branch, independent of the numbered training stages."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def build(table):
    x=json.loads((ROOT/'docs/artifacts/aerial_reorientation_feasibility/results.json').read_text())
    rows=[]
    for key,r in x['selected'].items():
        fine=next(v for v in x['validation'] if v['axis']==key and v['physics_dt']==.00125)
        rows.append([key,', '.join(f'{a:+.2f}' for a in r['rotation_vector_deg']),f'{r["final_angular_speed"]:.3f}',', '.join(f'{a:+.2f}' for a in fine['rotation_vector_deg'])])
    corrections=[r for r in x['validation'] if any(r['initial_angles'])]
    result = '''<section id="branch-aerial" class="stage"><div class="stage-label">Tor równoległy B1 · etap 1 zakończony</div><h2>Fizyczna możliwość obrotu w powietrzu</h2>
<p class="lead">Główny tor pozostaje przy v8: wysokość → prędkość, początkowe kąty zero. Ten eksperyment sprawdza osobno, czy Silver Badger potrafi zmienić orientację ruchem nóg. Nie jest kolejną wersją treningu ani wynikiem PPO.</p>
<p>Gałąź kodu: <code>experiment/aerial-reorientation-feasibility</code>; tor główny: <code>emergency_landing</code>. Profil v8 i test2.sh nie zostały zmienione w tym eksperymencie. Status: diagnostyka możliwości zakończona; uczenie orientowania jeszcze nie rozpoczęte.</p>
<h3>Co rzeczywiście zbadano</h3><p>361 deterministycznych kandydatów: zerowa akcja, symetryczne i przeciwne ruchy bioder, ud, łydek, kręgosłupa oraz skoordynowane sekwencje losowane z ustalonego seeda. Polecenia przechodzą przez rzeczywiste mapowanie residual PD, z akcjami w [-1,1]. Porównano cykl home → A → B → home z ruchem home → A i utrzymaniem nowej pozycji. Sterowanie 50 Hz, implicitfast 2,5 ms, rzeczywista grawitacja, swobodna baza, bez przyłożonych sił podtrzymujących. Nie ma narzuconej orientacji ani przesuwania bazy w czasie integracji.</p>
<p>Główny test trwa 0,8 s i zaczyna się na 20 m, żeby wykluczyć kontakt z podłożem. Ta wysokość służy izolacji dynamiki lotu, nie jest zadaniem lądowania ani propozycją rozszerzenia v8. Oryginalny model ma gęstość powietrza 1,2 i lepkość 2e-5; w teście głównym wyłączono oba parametry, aby oddzielić efekt bezwładnościowy od aerodynamicznego. W kontrolach na 1, 2 i 3 m przywrócono oryginalne powietrze i zatrzymano analizę przy pierwszym kontakcie. Wynik przed kontaktem pochodzi z ostatniej próbki sterowania, maksymalnie około 20 ms wcześniej.</p>
<h3>Wynik: utrzymanie pozycji nóg działa</h3><p>Przy utrzymaniu nowej konfiguracji uzyskano około 16,4° składowej roll lub 11,3° składowej pitch, z niemal zerową prędkością kątową po 0,8 s. Powtórzenie przy kroku 1,25 ms daje niemal te same wartości. To dowód możliwości zmiany orientacji tułowia w tym modelu. Nie jest jeszcze dowodem poprawnego ustawienia stóp ani bezpiecznego lądowania.</p>
<p>Powrót wszystkich poleceń do home cofa większość obrotu. Resztkowy roll wynosi około 2,3°, natomiast około 1° pozostałego pitch/yaw zmniejsza się mniej więcej o połowę po zmniejszeniu kroku symulacji. Tych małych wyników nie traktujemy jako mocnego dowodu użytecznego manewru. Wartości momentu pędu i odchylenia toru środka masy zapisano w danych; nie założono ich idealnego zachowania przez integrator.</p>'''+table(['Manewr','Wektor obrotu X,Y,Z [°], 2,5 ms','|ω| [rad/s]','Wektor obrotu przy 1,25 ms [°]'],rows)+'''
<p class="caption">To składowe wektora obrotu względem początkowej poziomej orientacji, nie kąty Eulera. Nazwa yaw_hold oznacza wybór według składowej yaw: towarzyszy jej około 16° roll, więc nie jest to niezależny obrót wokół osi yaw. Wybór: największa bezwzględna składowa końcowa spośród kandydatów bez kontaktów, z |ω| &lt;2 rad/s i momentami silników w nominalnych limitach. To wynik ograniczonego przeszukania, nie maksymalna zdolność robota.</p>
<h3>Kontrola: czy robot faktycznie prostuje przechył?</h3>'''+table(['Początkowe roll/pitch [°]','Przechył od pionu przed kontaktem [°]','Czas ostatniej próbki [s]','|ω| [rad/s]'],[[str(r['initial_angles'][:2]),f'{r["final_tilt_deg"]:.2f}',f'{r["final_time"]:.2f}',f'{r["final_angular_speed"]:.3f}'] for r in corrections])+'''
<p>To dwie otwarte, dobrane próby z 2 m, z oryginalnym powietrzem: -15° roll oraz -10° pitch. Pozostały przechył wynosi odpowiednio około 1,0° i 1,4°. Brak testu fazy kontaktu i statystyki sukcesu: nie przypisujemy tym próbom skuteczności lądowania >80%.</p>
<figure class="chart"><img src="../artifacts/aerial_reorientation_feasibility/orientation.png" alt="Przebiegi składowych orientacji podczas swobodnego lotu"><figcaption>Porównanie zerowej akcji, utrzymania nowej pozycji i cyklu wracającego do home.</figcaption></figure>
<figure><video controls preload="metadata" poster="media/branch-aerial-feasibility.png" src="media/branch-aerial-feasibility.mp4"></video><figcaption>Wizualizacja czterech swobodnych lotów, 4× wolniej. Kamera śledzi spadającą bazę, dlatego robot pozostaje w kadrze. Po końcu symulacji pokazano zatrzymaną ostatnią klatkę. Robot nie jest zawieszony.</figcaption></figure>
<h3>Co dalej w tym torze</h3><p>Najbardziej uzasadnione jest nauczenie polityki wyboru i utrzymania korzystnej konfiguracji nóg oraz przejścia z niej do amortyzacji. Nie należy na początku wymagać powrotu do home przed kontaktem. Kolejny eksperyment powinien ocenić stopy i bezpieczeństwo lądowania przy obu znakach przechyłu, zanim zwiększymy kąty. V8 pozostaje oddzielnym eksperymentem prędkościowym.</p>
<p><a href="../artifacts/aerial_reorientation_feasibility/results.json">Pełne wyniki i protokół</a> · <a href="../../experiments/analysis/probe_aerial_reorientation.py">Skrypt testu</a></p></section>'''

    cycles=ROOT/'docs/artifacts/aerial_reorientation_feasibility/cycles.json'
    if cycles.exists():
        data=json.loads(cycles.read_text());rows=[]
        for axis,(label,v) in enumerate(data['selected'].items()):
            rows.append([label,*[f"{abs(v[k]['rotation_vector_deg'][axis]):.3f}°" for k in ['coarse','fine','finer']],f"{v['finer']['joint_closure_max_deg']:.3f}°",f"{v['finer']['joint_speed_max_rad_s']:.4f}"])
        addition='<h3>Osobny test pełnego cyklu: start → ruch → powrót</h3><p>Rozszerzono zbiór do 1241 cykli, w tym 1000 nowych. Tym razem sprawdzano rzeczywiste domknięcie stawów: błąd pozycji każdego stawu poniżej 0,5°, prędkość każdego stawu poniżej 0,05 rad/s, prędkość kątowa korpusu poniżej 0,1 rad/s, brak kontaktów i momenty w nominalnych limitach. Kryteria przy kroku 2,5 ms spełniło 76 prób. Pierwsza tabela tego toru obejmowała powrót polecenia do home, bez tego ścisłego testu rzeczywistej pozycji; jej wyniku około 2,3° roll nie należy utożsamiać z dokładnie domkniętym cyklem.</p>'
        addition+=table(['Oś wyboru','Zysk 2,5 ms','Zysk 1,25 ms','Zysk 0,625 ms','Błąd powrotu stawów, max','Prędkość stawu, max [rad/s]'],rows)
        addition+='<p>Podane zyski to bezwzględne składowe wektora obrotu po 0,8 s, w próżni. Najlepszy zweryfikowany roll zachowuje około 0,7°, a nie kilkanaście stopni. Ruch zadany trwa 0,2 s; dalsze 0,6 s służy powrotowi i uspokojeniu. Nadal dopuszczamy do 0,5° błędu stawu, więc nie jest to matematycznie identyczna konfiguracja. Po 3 s diagnostycznego uspokajania błąd stawów spada do 0,013°, a roll pozostaje około 0,78°. Tego długiego testu, zaczynającego się na 100 m wyłącznie w celu uniknięcia kontaktu, nie traktujemy jako manewru dostępnego przy lądowaniu z 1–3 m.</p><p>Pitch i yaw maleją około dwukrotnie po każdym zmniejszeniu kroku: nie wykazano użytecznego, zbieżnego obrotu pełnym cyklem wokół tych osi. Dłuższe czekanie nie usuwa błędu: pozostająca niewielka prędkość kątowa, zależna od kroku, akumuluje pozorny zysk. Wyniki nie są górną granicą możliwości robota: przeszukano tylko rodzinę płynnych sekwencji home–A–B–home, bez optymalizacji pełnej trajektorii.</p><p>Wniosek dla dalszych prac: pełny cykl wymaga osobnego poszukiwania nieodwracalnej sekwencji skoordynowanych ruchów, np. zmiany bezwładności przedniej i tylnej części w różnych fazach. Obecne próby potwierdzają znacznie większą skuteczność zmiany i utrzymania konfiguracji niż jej zamknięcia przed lądowaniem.</p><p><a href="../artifacts/aerial_reorientation_feasibility/cycles.json">Wszystkie cykle, warunki domknięcia i testy kroku</a></p>'
        result=result.replace('</section>',addition+'</section>')
    return result
